        }

        const UiMenuRoundTripResult roundTrip =
            TriggerAndDismissKeyboardActivatedUiMenu(navigationView, virtualKey, uiThreadId, navigationView, SelfTest::Scale(2000ms), SelfTest::Scale(3000ms));

